import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const iceWolfScenarios=['ice-wolf-ordinary','ice-wolf-dedicated','ice-wolf-chanted-dedicated','ice-wolf-relative'] as const;
export type IceWolfScenario=typeof iceWolfScenarios[number];
export function isIceWolfScenario(name:string):name is IceWolfScenario{return (iceWolfScenarios as readonly string[]).includes(name);}
/** All modes begin before actual CHANT; tests execute required or optional preparation and the full intervening turn order. */
export function makeIceWolfScenario(_name:IceWolfScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;follower?:string;blessed?:boolean}={}){
 const ordinary=_name==='ice-wolf-ordinary',follower=options.follower??(ordinary?'メタルゴーレム':'水竜'),blessed=options.blessed??(options.follower===undefined&&!ordinary);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'凍気のアイエル');assignCharacter(s,b,'侍大将のシン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.magic_level=20+(options.level??7)-stats.magic_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;
 const axe=takeCard(s,a,'a2-p13-r1c1'),prayer=takeCard(s,a,'必勝の祈り'),fate=takeCard(s,c,'命運凶変'),evade=takeCard(s,b,'見切る'),maai=takeCard(s,b,'a2-p07-r1c1'),guard=follower==='none'?null:takeCard(s,b,follower);let blessing:string|null=null;if(blessed){blessing=takeCard(s,b,'祝福');s.players[b]!.hand=s.players[b]!.hand.filter(id=>id!==blessing);s.deck.unshift(blessing);}for(const id of [a,b,c,d])trimHand(s,id,axe,prayer,fate,evade,maai,...(guard?[guard]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(blessing)s.deck=[blessing,...s.deck.filter(id=>id!==blessing)];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`ICE_WOLF_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('ICE_WOLF_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('ICE_WOLF_IDS');}
 function advanceTo(target:string){for(let n=0;n<200;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===target)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==axe).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('ICE_WOLF_TURN');}throw Error('ICE_WOLF_TURN_LIMIT');}
 for(const id of [a,b,c,d]){const follower=id===b?guard:null;if(follower)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:follower});act(id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(blessing){act(a,{type:'PASS_ACTION'});advanceTo(a);if(!s.players[b]!.open.includes(blessing))throw Error('ICE_WOLF_BLESSING_DRAW');}return s;
}
